        public void DeepCopyIn(
            ITree item,
            ITreeGetter rhs,
            ErrorMaskBuilder? errorMask,
            TranslationCrystal? copyMask,
            bool deepCopy)
        {
            base.DeepCopyIn(
                (IFallout76MajorRecord)item,
                (IFallout76MajorRecordGetter)rhs,
                errorMask,
                copyMask,
                deepCopy: deepCopy);
            if ((copyMask?.GetShouldTranslate((int)Tree_FieldIndex.EDID) ?? true))
            {
                item.EDID = rhs.EDID;
            }
            if ((copyMask?.GetShouldTranslate((int)Tree_FieldIndex.ObjectPlacementDefaults) ?? true))
            {
                errorMask?.PushIndex((int)Tree_FieldIndex.ObjectPlacementDefaults);
                try
                {
                    item.ObjectPlacementDefaults.SetTo(
                        rhs.ObjectPlacementDefaults
                        .Select(r =>
                        {
                            return r.DeepCopy(
                                errorMask: errorMask,
                                default(TranslationCrystal));
                        }));
                }
                catch (Exception ex)
                when (errorMask != null)
                {
                    errorMask.ReportException(ex);
                }
                finally
                {
                    errorMask?.PopIndex();
                }
            }
            if ((copyMask?.GetShouldTranslate((int)Tree_FieldIndex.ObjectBounds) ?? true))
            {
                errorMask?.PushIndex((int)Tree_FieldIndex.ObjectBounds);
                try
                {
                    if ((copyMask?.GetShouldTranslate((int)Tree_FieldIndex.ObjectBounds) ?? true))
                    {
                        item.ObjectBounds = rhs.ObjectBounds.DeepCopy(
                            copyMask: copyMask?.GetSubCrystal((int)Tree_FieldIndex.ObjectBounds),
                            errorMask: errorMask);
                    }
                }
                catch (Exception ex)
                when (errorMask != null)
                {
                    errorMask.ReportException(ex);
                }
                finally
                {
                    errorMask?.PopIndex();
                }
            }
            if ((copyMask?.GetShouldTranslate((int)Tree_FieldIndex.Model) ?? true))
            {
                errorMask?.PushIndex((int)Tree_FieldIndex.Model);
                try
                {
                    if(rhs.Model is {} rhsModel)
                    {
                        item.Model = rhsModel.DeepCopy(
                            errorMask: errorMask,
                            copyMask?.GetSubCrystal((int)Tree_FieldIndex.Model));
                    }
                    else
                    {
                        item.Model = default;
                    }
                }
                catch (Exception ex)
                when (errorMask != null)
                {
                    errorMask.ReportException(ex);
                }
                finally
                {
                    errorMask?.PopIndex();
                }
            }
            if ((copyMask?.GetShouldTranslate((int)Tree_FieldIndex.PFIG) ?? true))
            {
                if(rhs.PFIG is {} PFIGrhs)
                {
                    item.PFIG = PFIGrhs.ToArray();
                }
                else
                {
                    item.PFIG = default;
                }
            }
            if ((copyMask?.GetShouldTranslate((int)Tree_FieldIndex.sigBaseObjects) ?? true))
            {
                item.sigBaseObjects = rhs.sigBaseObjects.ToArray();
            }
            if ((copyMask?.GetShouldTranslate((int)Tree_FieldIndex.HarvestSound) ?? true))
            {
                item.HarvestSound.SetTo(rhs.HarvestSound.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Tree_FieldIndex.SNDR) ?? true))
            {
                if(rhs.SNDR is {} SNDRrhs)
                {
                    item.SNDR = SNDRrhs.ToArray();
                }
                else
                {
                    item.SNDR = default;
                }
            }
            if ((copyMask?.GetShouldTranslate((int)Tree_FieldIndex.FULL) ?? true))
            {
                item.FULL = rhs.FULL?.DeepCopy();
            }
            if ((copyMask?.GetShouldTranslate((int)Tree_FieldIndex.CNAM) ?? true))
            {
                if(rhs.CNAM is {} CNAMrhs)
                {
                    item.CNAM = CNAMrhs.ToArray();
                }
                else
                {
                    item.CNAM = default;
                }
            }
            if ((copyMask?.GetShouldTranslate((int)Tree_FieldIndex.PFPC) ?? true))
            {
                if(rhs.PFPC is {} PFPCrhs)
                {
                    item.PFPC = PFPCrhs.ToArray();
                }
                else
                {
                    item.PFPC = default;
                }
            }
            if ((copyMask?.GetShouldTranslate((int)Tree_FieldIndex.VMAD) ?? true))
            {
                if(rhs.VMAD is {} VMADrhs)
                {
                    item.VMAD = VMADrhs.ToArray();
                }
                else
                {
                    item.VMAD = default;
                }
            }
            DeepCopyInCustom(
                item: item,
                rhs: rhs,
                errorMask: errorMask,
                copyMask: copyMask,
                deepCopy: deepCopy);
        }
        
